#!/usr/bin/env node

/**
 * ARE Context Loader Hook (PostToolUse → Read|Edit|Write|MultiEdit|Bash|Agent|Task)
 *
 * Fires after tool calls that touch project files. Candidate paths are taken
 * from `tool_input.file_path` / `tool_input.notebook_path` (Read, Edit, Write,
 * MultiEdit, NotebookEdit), or scanned out of `tool_input.command` (Bash) and
 * `tool_input.prompt` / `tool_input.description` (Agent, Task).
 *
 * Each resolved directory is walked upward to the project root. When a
 * directory contains an AGENTS.md generated by ARE, and it hasn't been loaded
 * yet this session, its content is emitted as additionalContext for Claude —
 * parents before children across the union of all walks.
 *
 * Deduplicates per session via temp file keyed by session_id.
 * Skips the project root (already loaded via CLAUDE.md → @AGENTS.md).
 */

import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';

/** Max directories walked per invocation (keeps the hook well under its timeout) */
const MAX_START_DIRS = 10;
/** Max unique path-like tokens taken from a scanned string */
const MAX_TOKENS = 50;
/** Strings longer than this are not scanned at all */
const MAX_SCAN_LENGTH = 20000;

let input = '';
process.stdin.setEncoding('utf8');
process.stdin.on('data', (chunk) => { input += chunk; });
process.stdin.on('end', () => {
  try {
    main(JSON.parse(input));
  } catch {
    // Malformed input — exit silently
  }
});

function main(data) {
  const projectRoot = data.cwd ? path.resolve(data.cwd) : '';

  const startDirs = collectStartDirs(data, projectRoot);
  if (startDirs.length === 0) return;

  // Deduplicate per session
  const sessionId = data.session_id || 'default';
  const dedupeDir = path.join(os.tmpdir(), 'are-context-loader');
  const dedupeFile = path.join(dedupeDir, sessionId + '.json');

  let seen = {};
  try {
    if (fs.existsSync(dedupeFile)) {
      seen = JSON.parse(fs.readFileSync(dedupeFile, 'utf8'));
    }
  } catch {}

  // Walk from each start directory up to (but not including) project root,
  // collecting all unseen candidate directories
  const candidates = [];
  const collected = new Set();
  for (const startDir of startDirs) {
    let dir = startDir;
    while (dir && dir !== projectRoot && dir !== path.dirname(dir)) {
      if (!seen[dir] && !collected.has(dir)) {
        collected.add(dir);
        candidates.push(dir);
      }
      dir = path.dirname(dir);
    }
  }

  // Parent context before child context (root-to-leaf) across all walks
  candidates.sort((a, b) => {
    const depthA = a.split(path.sep).length;
    const depthB = b.split(path.sep).length;
    if (depthA !== depthB) return depthA - depthB;
    return a < b ? -1 : a > b ? 1 : 0;
  });

  const parts = [];
  for (const dir of candidates) {
    const agentsMd = path.join(dir, 'AGENTS.md');
    if (!fs.existsSync(agentsMd)) continue;
    try {
      const content = fs.readFileSync(agentsMd, 'utf8');
      if (content.includes('Generated by agents-reverse-engineer')) {
        const relDir = projectRoot ? path.relative(projectRoot, dir) : dir;
        parts.push('## ARE Context: ' + relDir + '/AGENTS.md\n\n' + content);
        seen[dir] = true;
      }
    } catch {}
  }

  if (parts.length === 0) return;

  // Persist dedup state
  try {
    fs.mkdirSync(dedupeDir, { recursive: true });
    fs.writeFileSync(dedupeFile, JSON.stringify(seen));
  } catch {}

  // Output structured JSON — additionalContext is injected into Claude's conversation
  process.stdout.write(JSON.stringify({
    suppressOutput: false,
    hookSpecificOutput: {
      hookEventName: 'PostToolUse',
      additionalContext: parts.join('\n\n'),
    },
  }));
}

/**
 * Derive the ordered, de-duplicated list of absolute start directories for a
 * tool call, dispatching on `tool_name`.
 */
function collectStartDirs(data, projectRoot) {
  const tool = data.tool_name;
  const input = data.tool_input || {};

  let tokens;
  if (tool === 'Read' || tool === 'Edit' || tool === 'Write' || tool === 'MultiEdit') {
    tokens = input.file_path ? [input.file_path] : [];
  } else if (tool === 'NotebookEdit') {
    const notebookPath = input.notebook_path || input.file_path;
    tokens = notebookPath ? [notebookPath] : [];
  } else if (tool === 'Bash') {
    tokens = extractPathTokens(input.command);
  } else if (tool === 'Agent' || tool === 'Task') {
    tokens = extractPathTokens([input.prompt, input.description].filter(Boolean).join('\n'));
  } else {
    // Unknown or absent tool_name — fall back to file_path when present
    tokens = input.file_path ? [input.file_path] : [];
  }

  const dirs = [];
  const seenDirs = new Set();
  for (const token of tokens) {
    const dir = resolveStartDir(token, projectRoot);
    if (!dir || seenDirs.has(dir)) continue;
    seenDirs.add(dir);
    dirs.push(dir);
    if (dirs.length >= MAX_START_DIRS) break;
  }
  return dirs;
}

/**
 * Conservative scanner pulling path-like tokens (anything containing a `/`)
 * out of free-form text such as a Bash command or an agent prompt.
 */
function extractPathTokens(text) {
  if (!text || typeof text !== 'string') return [];
  if (text.length > MAX_SCAN_LENGTH) return [];

  const normalised = text.replace(/['"`]/g, ' ');
  const matches = normalised.match(/(?:[A-Za-z0-9._~@+-]*\/)+[A-Za-z0-9._~@+-]+\/?/g);
  if (!matches) return [];

  const tokens = [];
  const seenTokens = new Set();
  for (const match of matches) {
    const token = match.replace(/[,;:)\]}.]+$/, '');
    if (!token || seenTokens.has(token)) continue;
    seenTokens.add(token);
    tokens.push(token);
    if (tokens.length >= MAX_TOKENS) break;
  }
  return tokens;
}

/**
 * Resolve a raw token to the directory whose AGENTS.md chain should be loaded.
 * Returns null for tokens outside the project, non-existent paths, and the
 * project root itself.
 */
function resolveStartDir(token, projectRoot) {
  if (!token || typeof token !== 'string') return null;

  const abs = path.resolve(projectRoot || process.cwd(), token);

  // Only trigger for paths within the project
  if (projectRoot && abs !== projectRoot && !abs.startsWith(projectRoot + path.sep)) return null;

  let stats;
  try {
    stats = fs.statSync(abs);
  } catch {
    return null;
  }

  let dir;
  if (stats.isDirectory()) dir = abs;
  else if (stats.isFile()) dir = path.dirname(abs);
  else return null;

  // Skip project root — already loaded via CLAUDE.md → @AGENTS.md
  if (dir === projectRoot) return null;

  return dir;
}
